from pathlib import Path
import json
R=Path(__file__).resolve().parents[1];p=R/'content.json';data=json.loads(p.read_text());questions=data['questions'][:40]
films=[('interstellar','Интерстеллар',2014,['Гравитация','Интерстеллар','Контакт']),('forrest-gump','Форрест Гамп',1994,['Форрест Гамп','Зелёная миля','Изгой']),('the-truman-show','Шоу Трумана',1998,['Лжец, лжец','Кабельщик','Шоу Трумана']),('shutter-island','Остров проклятых',2010,['Начало','Остров проклятых','Отступники']),('titanic','Титаник',1997,['Титаник','Посейдон','Перл-Харбор']),('mission-impossible','Миссия невыполнима',1996,['Скорость','Скала','Миссия невыполнима']),('gladiator','Гладиатор',2000,['Троя','Гладиатор','Александр']),('arrival','Прибытие',2016,['Прибытие','Контакт','Война миров']),('saving-private-ryan','Спасти рядового Райана',1998,['Тонкая красная линия','Дюнкерк','Спасти рядового Райана']),('the-wolf-of-wall-street','Волк с Уолл-стрит',2013,['Игра на понижение','Волк с Уолл-стрит','Уолл-стрит'])]
for i,(slug,title,year,opts) in enumerate(films):questions.append(dict(id='poster_'+slug,type='frame',category='УЗНАЙ ПОСТЕР',text='Из какого фильма этот постер?',options=opts,correct=opts.index(title),fact=f'Это постер фильма «{title}» ({year}).',source='https://www.paramount.com/movies/'+slug,topic=slug.replace('-','_'),asset_index=40+i,voice_id='poster_question_v09',image='res://assets/projection/modern/'+slug+'.jpg',image_kind='poster',year=year))
gestures=[('forrest_actor','Главного героя «Форреста Гампа» сыграл Том Хэнкс?',True,'Главную роль сыграл Том Хэнкс.','forrest-gump'),('truman_director','«Шоу Трумана» снял Стивен Спилберг?',False,'Режиссёр — Питер Уир.','the-truman-show'),('shutter_director','«Остров проклятых» снял Кристофер Нолан?',False,'Режиссёр — Мартин Скорсезе.','shutter-island'),('arrival_actor','Главную героиню «Прибытия» сыграла Эми Адамс?',True,'Луизу Бэнкс сыграла Эми Адамс.','arrival'),('mission_year','Первая «Миссия невыполнима» вышла в 2006 году?',False,'Первый фильм вышел в 1996 году.','mission-impossible'),('gladiator_director','«Гладиатора» снял Ридли Скотт?',True,'Режиссёр — Ридли Скотт.','gladiator'),('titanic_director','«Титаник» снял Джеймс Кэмерон?',True,'Режиссёр — Джеймс Кэмерон.','titanic'),('forrest_composer','Музыку к «Форресту Гампу» написал Ханс Циммер?',False,'Композитор — Алан Сильвестри.','forrest-gump')]
for i,(name,text,answer,fact,slug) in enumerate(gestures):questions.append(dict(id='gesture_'+name+'_v09',type='gesture',category='ДА ИЛИ НЕТ',text=text,options=['Нет','Да'],correct=int(answer),fact=fact,source='https://www.paramount.com/movies/'+slug,topic=slug.replace('-','_'),asset_index=50+i,voice_id='gesture_'+name+'_v09'))
data['questions']=questions
data['intro']=[dict(id='intro_short_0_v09',text='Проснулся? Проверим, что ты знаешь о кино.',action='wake'),dict(id='intro_short_1_v09',text='Выбирай карточку взглядом и щелчком. Да — кивни. Нет — покачай головой.',action='answers'),dict(id='intro_short_2_v09',text='Восемнадцать секунд. Одна ошибка — дубль. Вторая — конец. Ответишь на всё — отпущу.',action='timer')]
p.write_text(json.dumps(data,ensure_ascii=False,indent=2));print('CONTENT',len(questions))
